head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.SECUGRP_ID = "PF";                          // 상장형수익증권 (원본 scwin.fr_SecuGrpId)
scwin.POPUP_PATH = "/ui/lst/pf/";                 // 투자유의·매매거래정지 팝업 배포 경로 (원본 리터럴 — pf 공통 계약 §2)
scwin.HALT_RSN_CD = "424";                        // 매매거래정지 사유코드 (원본 arrRsn1)
scwin.HALT_RSN_NM = "투자유의종목(상장형 수익증권)";   // 매매거래정지 사유명 (원본 arrRsn2)
scwin.SELECT_GUBUN_ALL = "3";                     // 선택 구분 1 종목 · 2 발행회사 · 3 전체 (원본 select_gubun)
scwin.TAB_HALT = 5;                               // [매매거래정지 및 정지해제] 탭 index
scwin.TAB_NEW_FROM = 2;                           // [신규]는 [지정](2) ~ [매매거래정지](5) 탭에서만 보인다 (원본 MaxTab_1_onchange)
scwin.mktId = "";      // 사용자 시장 (원본 scwin.fr_MktId = 세션 market)
scwin.todayDd = "";    // 오늘(서버 날짜 yyyyMMdd) — 탭을 처음 열 때 조회일자 기본값, [신규] 과거일 판정
scwin.nextDd = "";     // 익영업일 — [지정예고]~[매매거래정지] 탭 지정일 기본값 (원본 scwin.calDd)
// 탭별 정보 — index 는 MaxTab_1 의 탭 순서. 투자유의 5종은 구분코드·등록 팝업이 다르고, 매매거래정지는 조회 API 와 팝업 3종이 따로다.
scwin.TABS = [
    { gubunCd : "01", name : "최초적출", dlt : "dlt_selectList1", grd : "grd_1", popupId : "ULDSTF09341", width : 800, height : 650 },
    { gubunCd : "02", name : "지정예고", dlt : "dlt_selectList2", grd : "grd_2", popupId : "ULDSTF09342", width : 800, height : 650 },
    { gubunCd : "03", name : "지정", dlt : "dlt_selectList3", grd : "grd_3", popupId : "ULDSTF09343", width : 1000, height : 600 },
    { gubunCd : "04", name : "지정연장", dlt : "dlt_selectList4", grd : "grd_4", popupId : "ULDSTF09344", width : 800, height : 650 },
    { gubunCd : "05", name : "지정해제", dlt : "dlt_selectList5", grd : "grd_5", popupId : "ULDSTF09345", width : 800, height : 650 },
    { gubunCd : "06", name : "매매거래정지 및 정지해제", dlt : "dlt_selectList6", grd : "grd_6", popupId : "", width : 0, height : 0 }
];

// 매매거래정지 팝업 — haltTpCd 0 지정 · 1 해제 · 2 지정 및 해제. 높이는 원본의 신규·수정 불일치를 pf 공통 계약 §2 대로 통일
scwin.HALT_POPUPS = {
    "0" : { popupId : "ULDSTF09043", name : "매매거래정지 지정", height : 800 },
    "1" : { popupId : "ULDSTF09044", name : "매매거래정지 해제", height : 900 },
    "2" : { popupId : "ULDSTF09042", name : "매매거래정지 지정 및 해제", height : 900 }
};

// 매매거래정지 비고 기본 문구 (원본 fn_GetParNewTrdHalt. 해제 문구는 종목해제 fn_GetParRelease 의 안내 문구와 같다)
scwin.HALT_REMK = {
    "0" : "상기 종목은 시장상황급변 등으로 투자자보호 및 시장안정을 위하여 매매거래가 정지됩니다.\r\n"
        + "매매거래정지 해제 시 별도의 시장안내가 있을 예정이며,\r\n"
        + "매매거래 재개시 투자유의종목으로서 3매매거래일(지정단위기간) 단위의 단일가매매로 거래가 재개됩니다.",
    "1" : "상기 종목은 매매거래정지 사유가 해소됨에 따라 매매거래정지가 해제되며,\r\n"
        + "매매거래정지해제일부터 투자유의종목으로서 3매매거래일(지정단위기간) 단위의 단일가매매로 거래가 재개됩니다.",
    "2" : "상기 종목은 투자유의종목 지정단위기간(3매매거래일)이 종료하는 날에 장종료시 실시간 괴리율이\r\n"
        + "규정상 의무범위의 3배 이상에 해당하여 1일간 매매거래가 정지됩니다.\r\n"
        + "매매거래정지해제일부터는 지정단위기간이 새롭게 시작되며, 단일가 매매로 거래가 재개됩니다\r\n\r\n"
        + "※ 시장상황급변 등 투자자보호 및 시장안정을 위해 매매거래정지 기간은 연장될 수 있습니다."
};

// 원본 : /pf/ULDSTF09340.gfm (상장형수익증권 투자유의) — W-Craft 1차 변환 + API 적용 개발 사본(ui/ULDSTF09340/ULDSTF09340.xml)
/*
 * 화면 동작
 *  - 탭 6종(최초적출·지정예고·지정·지정연장·지정해제·매매거래정지 및 정지해제)마다 조회일자로 목록을 조회한다.
 *    조회 전에 그날의 시장정보 배치실행 여부를 받아 하단에 보여 준다. 탭을 바꾸면 그 탭을 다시 조회한다.
 *  - 투자유의 탭의 행 더블클릭 또는 [신규]는 그 탭의 등록 팝업(ULDSTF09341~09345)을 연다.
 *  - [매매거래정지] 탭은 행 구분·업무처리번호와 하단 [신규등록구분]으로 매매거래정지 팝업 3종(ULDSTF09042~09044)을 고른다.
 *  - 팝업이 저장하고 닫히거나 창 닫기(X)로 닫히면 그 탭을 다시 조회하고 연 행을 다시 선택한다(pf 공통 계약 재조회 규약).
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF09340/ULDSTF09340.md (§번호는 이 문서의 절)
 */

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09340.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 로딩 — 사용자 시장·오늘 → 첫 탭 조회일자 → 하단 버튼 상태 → 익영업일 조회. 첫 화면은 조회하지 않는다(원본 그대로).
 * 탭 본문 안 달력·조회 영역 바인딩은 탭이 처음 그려질 때 scwin.MaxTab_1_ontabload 가 한다(규칙 45). (원본 init — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 사용자 시장·오늘. 첫 탭(최초적출)은 tabControl 초기화 때 이미 그려져 있어(그 탭 ontabload 는 init 보다 먼저) 조회일자를 여기서 넣는다
    scwin.mktId = $c.session.getUserInfo("market");
    scwin.todayDd = $c.date.getServerDateTime();
    cal_searchDate1.setValue(scwin.todayDd);

    // 2) 첫 탭 하단 버튼 — [신규]·신규등록구분 숨김
    scwin.applyTabButtons(0);

    // 3) 익영업일 — 지정예고~매매거래정지 탭 지정일 기본값
    await scwin.selectNextDay();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.MaxTab_1_ontabload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 탭 로드 — 처음 그려진 탭의 조회일자 기본값(오늘)·달력 형식 검사(규칙 37)·조회 영역 Enter 키(규칙 22)를 건다(규칙 45).
 * 첫 탭은 init 보다 먼저 오므로 조회일자는 init 이 넣는다. (원본 init·MaxTab_1_onchange 의 isFirstN 분기 — §3·§4)
 * @param {String} tabId 엔진 탭 id("MaxTab_1_tab_{tabs id}")
 * @param {Number} index 로드된 탭 index
 * @param {String} userTabId w2:tabs id
 * @returns
 * @hidden N
 */
scwin.MaxTab_1_ontabload = async function (tabId, index, userTabId) {
    try {
        if (index === 0) {            // [최초적출]
            $c.date.checkCalendarFormat(cal_searchDate1, "yyyyMMdd");
            $c.win.setEnterKeyEvent(pan_cmd1, scwin.btn_search1_onclick);
        } else if (index === 1) {     // [지정예고]
            scwin.setDefaultDate(cal_searchDate2);
            $c.date.checkCalendarFormat(cal_searchDate2, "yyyyMMdd");
            $c.win.setEnterKeyEvent(pan_cmd2, scwin.btn_search2_onclick);
        } else if (index === 2) {     // [지정]
            scwin.setDefaultDate(cal_searchDate3);
            $c.date.checkCalendarFormat(cal_searchDate3, "yyyyMMdd");
            $c.win.setEnterKeyEvent(pan_cmd3, scwin.btn_search3_onclick);
        } else if (index === 3) {     // [지정연장]
            scwin.setDefaultDate(cal_searchDate4);
            $c.date.checkCalendarFormat(cal_searchDate4, "yyyyMMdd");
            $c.win.setEnterKeyEvent(pan_cmd4, scwin.btn_search4_onclick);
        } else if (index === 4) {     // [지정해제]
            scwin.setDefaultDate(cal_searchDate5);
            $c.date.checkCalendarFormat(cal_searchDate5, "yyyyMMdd");
            $c.win.setEnterKeyEvent(pan_cmd5, scwin.btn_search5_onclick);
        } else if (index === 5) {     // [매매거래정지 및 정지해제]
            scwin.setDefaultDate(cal_searchDate6);
            $c.date.checkCalendarFormat(cal_searchDate6, "yyyyMMdd");
            $c.win.setEnterKeyEvent(pan_cmd6, scwin.btn_search6_onclick);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09340.MaxTab_1_ontabload" });
    }
};

/**
 * @method
 * @name scwin.MaxTab_1_onchange
 * @author Inswave
 * @date 2026. 10. 30
 * @description 탭 변경 — 하단 버튼을 그 탭에 맞추고 그 탭을 조회한다. (원본 MaxTab_1_onchange — §4)
 * @param {String} tabId 엔진 탭 id
 * @param {Number} index 선택된 탭 index
 * @param {String} userTabId w2:tabs id
 * @returns
 * @hidden N
 */
scwin.MaxTab_1_onchange = async function (tabId, index, userTabId) {
    try {
        scwin.applyTabButtons(index);
        await scwin.searchList(index);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09340.MaxTab_1_onchange" });
    }
};

/**
 * @method
 * @name scwin.btn_search1_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description [최초적출] 조회 버튼 클릭 (조회 영역 Enter 키도 이 핸들러)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_search1_onclick = async function (e) {
    try {
        await scwin.searchList(0);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09340.btn_search1_onclick" });
    }
};

