/**
 * @method
 * @name scwin.grd_1_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description [최초적출] 목록 더블클릭 — 그 행으로 최초적출 팝업(ULDSTF09341)을 연다.
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 열 id
 * @returns
 * @hidden N
 */
scwin.grd_1_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        if (rowIndex < 0) return;    // 목록 조회가 끝나기 전 더블클릭 (원본 주석)
        await scwin.openWarnPopup(0, rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09340.grd_1_oncelldblclick" });
    }
};

