/**
 * @method
 * @name scwin.grd_6_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description [매매거래정지 및 정지해제] 목록 더블클릭 — 행 구분·업무처리번호로 매매거래정지 팝업을 골라 연다.
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 열 id
 * @returns
 * @hidden N
 */
scwin.grd_6_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        if (rowIndex < 0) return;
        await scwin.openHaltFromRow(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09340.grd_6_oncelldblclick" });
    }
};

/**
 * @method
 * @name scwin.btn_regist_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description [신규] 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_regist_onclick = async function (e) {
    try {
        await scwin.openNew();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09340.btn_regist_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_excel_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description [엑셀다운로드] 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_excel_onclick = async function (e) {
    try {
        await scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09340.btn_excel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectNextDay
 * @author Inswave
 * @date 2026. 10. 30
 * @description 익영업일 조회 — 지정예고~매매거래정지 탭 지정일 기본값으로 둔다. (원본 fn_cal_dd — §5.1)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectNextDay = async function () {
    const sbmOptions = {
        id : "sbm_nextDay",
        method : "get",
        action : "/api/listing/lstproc/pf/invst-warn/select-nextday",
        target : "dma_cand=body",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;
    if (!result.responseJSON?.success) return false;    // 실패 안내는 공통 오류 핸들러

    scwin.nextDd = String(dma_cand.get("nextDd") ?? "");
    return true;
};

/**
 * @method
 * @name scwin.selectClsStatus
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회일자의 마감·진행상태 조회 — 시장정보 배치실행 여부(ibx_clsDtl 은 dma_cls.clsYn 에 바인딩)를 받는다. (원본 fn_invstwarn_cls — §5.2)
 * @param {String} trdDd 조회일자 (yyyyMMdd)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectClsStatus = async function (trdDd) {
    const sbmOptions = {
        id : "sbm_cls",
        method : "get",
        action : "/api/listing/lstproc/pf/invst-warn/select-md-progm-prog",
        target : "dma_cls=body",
        isProcessMsg : false
    };
    const requestData = {
        progsDd : trdDd,    // 처리일자
        trdDd : trdDd       // 거래일자
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return false;
    return result.responseJSON?.success === true;
};

/**
 * @method
 * @name scwin.selectList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 탭 목록 조회 — 마감·진행상태를 먼저 받고 그 탭 구분코드로 목록을 조회해 건수를 적는다.
 * 투자유의 5종은 select-list, 매매거래정지는 select-list-trdhalt. (원본 fn_search_1 ~ fn_search_6 — §5.3)
 * @param {Number} index 탭 index (0~5)
 * @param {String} trdDd 조회일자 (yyyyMMdd)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectList = async function (index, trdDd) {
    const tab = scwin.TABS[index];
    await scwin.selectClsStatus(trdDd);

    const sbmOptions = {
        id : "sbm_selectList" + (index + 1),
        method : "get",
        action : "/api/listing/lstproc/pf/invst-warn/select-list",
        target : tab.dlt + "=body",
        gridview : tab.grd,
        isProcessMsg : false
    };
    if (index === scwin.TAB_HALT) {
        sbmOptions.action = "/api/listing/lstproc/pf/invst-warn/select-list-trdhalt";
    }
    const requestData = {
        trdDd : trdDd,                   // 조회일자
        secugrpId : scwin.SECUGRP_ID,    // 증권그룹ID
        gubunCd : tab.gubunCd            // 구분코드 01 최초적출 ~ 06 매매거래정지
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return false;
    if (!result.responseJSON?.success) return false;    // 실패 안내는 공통 오류 핸들러

    tbx_totCnt.setValue(scwin.getTabComp(index).dlt.getRowCount());
    return true;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.getTabComp
 * @author Inswave
 * @date 2026. 10. 30
 * @description 탭 index 의 조회일자 달력·그리드·목록을 돌려준다. 탭 본문은 처음 선택될 때 그려지므로 부르는 시점에 그 탭이 그려져 있어야 한다.
 * @param {Number} index 탭 index (0~5)
 * @returns {Object} { cal, grd, dlt }
 * @hidden N
 */
scwin.getTabComp = function (index) {
    switch (index) {
        case 0 : return { cal : cal_searchDate1, grd : grd_1, dlt : dlt_selectList1 };
        case 1 : return { cal : cal_searchDate2, grd : grd_2, dlt : dlt_selectList2 };
        case 2 : return { cal : cal_searchDate3, grd : grd_3, dlt : dlt_selectList3 };
        case 3 : return { cal : cal_searchDate4, grd : grd_4, dlt : dlt_selectList4 };
        case 4 : return { cal : cal_searchDate5, grd : grd_5, dlt : dlt_selectList5 };
        case 5 : return { cal : cal_searchDate6, grd : grd_6, dlt : dlt_selectList6 };
    }
    return null;
};

/**
 * @method
 * @name scwin.setDefaultDate
 * @author Inswave
 * @date 2026. 10. 30
 * @description 탭을 처음 열 때 조회일자가 비어 있으면 오늘로 채운다. (원본 MaxTab_1_onchange 의 isFirstN 분기)
 * @param {Object} cal 조회일자 달력
 * @returns
 * @hidden N
 */
scwin.setDefaultDate = function (cal) {
    if (!$c.util.isEmpty(scwin.todayDd) && $c.util.isEmpty(cal.getValue())) {
        cal.setValue(scwin.todayDd);
    }
};

/**
 * @method
 * @name scwin.applyTabButtons
 * @author Inswave
 * @date 2026. 10. 30
 * @description 하단 버튼을 탭에 맞춘다 — [신규]는 지정~매매거래정지 탭, 신규등록구분(라벨·콤보)은 매매거래정지 탭에서만 보인다. (원본 init·MaxTab_1_onchange — §6.1)
 * @param {Number} index 탭 index (0~5)
 * @returns
 * @hidden N
 */
scwin.applyTabButtons = function (index) {
    if (index >= scwin.TAB_NEW_FROM) {
        btn_regist.show("");
    } else {
        btn_regist.hide();
    }

    if (index === scwin.TAB_HALT) {
        tbx_registType.show("");
        sbx_registType.show("");
    } else {
        tbx_registType.hide();
        sbx_registType.hide();
    }
};

/**
 * @method
 * @name scwin.searchList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 검증 후 탭 목록 조회 — 조회일자가 비었거나 날짜 형식이 아니면 안내하고 멈춘다. (원본 btn_searchN_onclick + fn_search_N 입력 검사 — §6.2)
 * @param {Number} index 탭 index (0~5)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.searchList = async function (index) {
    const comp = scwin.getTabComp(index);
    const trdDd = comp.cal.getValue();

    if ($c.util.isEmpty(trdDd)) {
        await $c.win.alert($c.data.getMessage("com_req_input", "조회일자"));
        comp.cal.focus();
        return false;
    }
    if (!$c.validate.isValidDate(trdDd)) {
        await $c.win.alert($c.data.getMessage("com_date_compare_0014"));
        comp.cal.focus();
        return false;
    }
    return await scwin.selectList(index, trdDd);
};

/**
 * @method
 * @name scwin.getEmptyInfo
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규([신규] 버튼)용 빈 행 정보. (원본 btn_regist_onclick 의 scwin.isuCd 등 비우기)
 * @returns {Object} 행 정보 (모두 "")
 * @hidden N
 */
scwin.getEmptyInfo = function () {
    return { bzProcsNo : "", isuCd : "", isuNm : "", isurCd : "", isurNm : "", fstDtectDd : "", haltTpCd : "" };
};

/**
 * @method
 * @name scwin.getRowInfo
 * @author Inswave
 * @date 2026. 10. 30
 * @description 탭 목록 행의 값을 팝업 data 로 쓸 행 정보로 꺼낸다. 발행회사명·정지해제구분은 매매거래정지 탭에만 있다.
 * (원본 grd_N_oncelldblclick 이 scwin.vBzProcsNo·isuCd·isuNm·isurCd·isurNm·fstDtectDd 전역에 넣던 값)
 * @param {Number} index 탭 index (0~5)
 * @param {Number} rowIndex 행 인덱스
 * @returns {Object} { bzProcsNo, isuCd, isuNm, isurCd, isurNm, fstDtectDd, haltTpCd }
 * @hidden N
 */
scwin.getRowInfo = function (index, rowIndex) {
    const dlt = scwin.getTabComp(index).dlt;
    const isHalt = (index === scwin.TAB_HALT);

    return {
        bzProcsNo : String(dlt.getCellData(rowIndex, "bzProcsNo") ?? ""),
        isuCd : String(dlt.getCellData(rowIndex, "isuCd") ?? ""),
        isuNm : String(dlt.getCellData(rowIndex, "isuNm") ?? ""),
        isurCd : String(dlt.getCellData(rowIndex, "isurCd") ?? ""),
        isurNm : isHalt ? String(dlt.getCellData(rowIndex, "isurNm") ?? "") : "",
        fstDtectDd : String(dlt.getCellData(rowIndex, "fstDtecDd") ?? ""),
        haltTpCd : isHalt ? String(dlt.getCellData(rowIndex, "haltDesnrelsTpCd") ?? "") : ""
    };
};

/**
 * @method
 * @name scwin.openNew
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 — 과거 조회일자면 안내하고 멈춘다. 매매거래정지 탭은 신규등록구분으로, 그 밖은 그 탭 등록 팝업을 빈 값으로 연다. (원본 btn_regist_onclick — §6.3)
 * @returns
 * @hidden N
 */
scwin.openNew = async function () {
    const index = MaxTab_1.getSelectedTabIndex();
    const inqDd = scwin.getTabComp(index).cal.getValue();

    if (inqDd < scwin.todayDd) {
        await $c.win.alert("과거 조회일자인 경우 조회만 가능합니다.");
        return;
    }

    if (index === scwin.TAB_HALT) {
        await scwin.openHaltNew(inqDd);
        return;
    }
    await scwin.openWarnPopup(index, -1);
};

/**
 * @method
 * @name scwin.buildWarnParam
 * @author Inswave
 * @date 2026. 10. 30
 * @description 투자유의 등록 팝업(ULDSTF09341~09345)에 넘길 data. 키는 pf 공통 계약 §2(투자유의 5종) — 원본 fr_MktId 는 mktId 로 정정. (원본 fn_GetParNew·fn_GetParUpdate — §6.4)
 * @param {Object} info 행 정보 (신규는 빈 값)
 * @param {String} inqDd 조회일자
 * @param {String} designDd 지정일 기본값
 * @returns {Object} 팝업 data
 * @hidden N
 */
scwin.buildWarnParam = function (info, inqDd, designDd) {
    return {
        isuCd : info.isuCd,                 // 종목코드
        isuNm : info.isuNm,                 // 종목명
        secugrpId : scwin.SECUGRP_ID,       // 증권그룹ID
        mktId : scwin.mktId,                // 사용자 시장 (원본 fr_MktId)
        bzProcsNo : info.bzProcsNo,         // 업무처리번호 — 신규 ""
        designDd : designDd,                // 지정일 기본값
        inqDd : inqDd,                      // 조회일자
        fstDtectDd : info.fstDtectDd,       // 최초지정일
        isurCd : info.isurCd                // 발행회사코드
    };
};

/**
 * @method
 * @name scwin.openWarnPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 투자유의 탭의 등록 팝업(ULDSTF09341~09345)을 data 로 열고 닫힐 때까지 기다린다. 지정일 기본값은 [최초적출]이면 조회일자,
 * 그 밖은 익영업일이다. 팝업이 저장하고 닫혔거나(isSaved) 창 닫기(X)로 닫혔으면 그 탭을 다시 조회하고 연 행을 다시 선택한다.
 * (원본 grd_N_oncelldblclick + fn_new_create_frame_1~5, 팝업의 refreshParent — §6.4, 가이드 §6.5)
 * @param {Number} index 탭 index (0~4)
 * @param {Number} rowIndex 행 인덱스. 신규는 -1
 * @returns
 * @hidden N
 */
scwin.openWarnPopup = async function (index, rowIndex) {
    const tab = scwin.TABS[index];
    const info = (rowIndex >= 0) ? scwin.getRowInfo(index, rowIndex) : scwin.getEmptyInfo();
    const inqDd = scwin.getTabComp(index).cal.getValue();
    const designDd = (index === 0) ? inqDd : scwin.nextDd;

    const options = {
        id : tab.popupId,
        popupName : $c.lc.getSecuGrpNm(scwin.SECUGRP_ID) + " 투자유의종목 " + tab.name,
        width : tab.width,
        height : tab.height,
        frameModal : "top",
        type : "pageFramePopup"
    };
    const res = await $c.win.openPopup(scwin.POPUP_PATH + tab.popupId + ".xml", options, scwin.buildWarnParam(info, inqDd, designDd));

    // 저장하고 닫힘 또는 창 닫기(X — 저장 여부를 모르므로 다시 조회) — pf 공통 계약 재조회 규약
    if (res?.isSaved !== true && res?.isCloseButtonClick !== true) return;
    if (!await scwin.searchList(index)) return;
    scwin.restoreRow(index, info.bzProcsNo, info.isuCd, rowIndex);
};

/**
 * @method
 * @name scwin.openHaltNew
 * @author Inswave
 * @date 2026. 10. 30
 * @description 매매거래정지 신규 — 신규등록구분을 고르지 않았으면 안내하고 멈춘다. (원본 fn_new_create_frame_6 — §6.5)
 * @param {String} inqDd 조회일자
 * @returns
 * @hidden N
 */
scwin.openHaltNew = async function (inqDd) {
    const haltTpCd = sbx_registType.getValue();
    if ($c.util.isEmpty(haltTpCd)) {
        await $c.win.alert($c.data.getMessage("com_req_select", "신규등록구분"));
        sbx_registType.focus();
        return;
    }

    const info = scwin.getEmptyInfo();
    await scwin.openHaltPopup(haltTpCd, scwin.buildHaltNewParam(haltTpCd, info, inqDd), info, -1);
};

/**
 * @method
 * @name scwin.openHaltFromRow
 * @author Inswave
 * @date 2026. 10. 30
 * @description 매매거래정지 목록 행으로 팝업을 고른다.
 * ① 업무처리번호가 없는 해제 행 — 같은 종목·최초지정일의 정지 지정 건 번호로 해제 팝업(못 찾으면 ③ 신규 해제)
 * ② 업무처리번호가 있는 행 — 그 구분의 팝업을 수정으로(구분이 비면 지정 및 해제)
 * ③ 업무처리번호가 없는 행 — 신규. 정지 행은 신규등록구분이 「지정」이 아니면 「지정 및 해제」, 그 밖은 행 구분으로
 * (원본 grd_6_oncelldblclick·fn_GetParRelease·fn_update_create_frame_trdHalt — §6.5)
 * @param {Number} rowIndex 행 인덱스
 * @returns
 * @hidden N
 */
scwin.openHaltFromRow = async function (rowIndex) {
    const info = scwin.getRowInfo(scwin.TAB_HALT, rowIndex);
    const inqDd = cal_searchDate6.getValue();

    // ① 종목해제 — 원본 Gauce 조회(halt_desnrels_0) 대신 같은 목록의 정지 지정 행에서 번호를 찾는다(§8 #4)
    if ($c.util.isEmpty(info.bzProcsNo) && info.haltTpCd === "1") {
        const designBzProcsNo = scwin.findHaltDesignBzProcsNo(info.isuCd, info.fstDtectDd);
        if (!$c.util.isEmpty(designBzProcsNo)) {
            await scwin.openHaltPopup("1", scwin.buildHaltReleaseParam(info, designBzProcsNo, inqDd), info, rowIndex);
            return;
        }
    }

    // ② 수정
    if (!$c.util.isEmpty(info.bzProcsNo)) {
        const haltTpCd = $c.util.isEmpty(info.haltTpCd) ? "2" : info.haltTpCd;    // 구분이 없는 건 — 원본 임시 방어로직
        await scwin.openHaltPopup(haltTpCd, scwin.buildHaltUpdateParam(haltTpCd, info, inqDd), info, rowIndex);
        return;
    }

    // ③ 신규
    if (info.haltTpCd === "0") {
        if (sbx_registType.getValue() !== "0") {
            sbx_registType.setValue("2");     // 정지 행 — 지정 및 해제
        }
    } else {
        sbx_registType.setValue(info.haltTpCd);
    }
    const haltTpCd = sbx_registType.getValue();
    await scwin.openHaltPopup(haltTpCd, scwin.buildHaltNewParam(haltTpCd, info, inqDd), info, rowIndex);
};

/**
 * @method
 * @name scwin.findHaltDesignBzProcsNo
 * @author Inswave
 * @date 2026. 10. 30
 * @description 매매거래정지 목록에서 같은 종목·최초지정일의 정지 지정(구분 0) 행 업무처리번호를 찾는다.
 * (원본 종목해제의 Gauce 조회 halt_desnrels_0 — 대응 API 가 화면에 없어 목록 대조로 대체, §8 #4·§10)
 * @param {String} isuCd 종목코드
 * @param {String} fstDtectDd 최초지정일
 * @returns {String} 업무처리번호 (없으면 "")
 * @hidden N
 */
scwin.findHaltDesignBzProcsNo = function (isuCd, fstDtectDd) {
    const rowCount = dlt_selectList6.getRowCount();
    for (let i = 0; i < rowCount; i++) {
        const bzProcsNo = String(dlt_selectList6.getCellData(i, "bzProcsNo") ?? "");
        if (String(dlt_selectList6.getCellData(i, "haltDesnrelsTpCd") ?? "") === "0"
            && String(dlt_selectList6.getCellData(i, "isuCd") ?? "") === isuCd
            && String(dlt_selectList6.getCellData(i, "fstDtecDd") ?? "") === fstDtectDd
            && !$c.util.isEmpty(bzProcsNo)) {
            return bzProcsNo;
        }
    }
    return "";
};

/**
 * @method
 * @name scwin.buildHaltNewParam
 * @author Inswave
 * @date 2026. 10. 30
 * @description 매매거래정지 신규 팝업 data. 키는 pf 공통 계약 §2(매매거래정지 3종) — select_gubun→selectGubun, fr_MktId→mktId,
 * arrRsn1/2/3→rsnCd/rsnNm/rsnDsc 로 정정. (원본 fn_GetParNewTrdHalt — §6.5)
 * @param {String} haltTpCd 정지해제구분 0 지정 · 1 해제 · 2 지정 및 해제
 * @param {Object} info 행 정보 (신규 버튼이면 빈 값)
 * @param {String} inqDd 조회일자
 * @returns {Object} 팝업 data
 * @hidden N
 */
scwin.buildHaltNewParam = function (haltTpCd, info, inqDd) {
    return {
        isurCd : info.isurCd,                       // 발행회사코드
        isurNm : info.isurNm,                       // 발행회사명
        secugrpId : scwin.SECUGRP_ID,               // 증권그룹ID
        mktId : scwin.mktId,                        // 사용자 시장 (원본 fr_MktId)
        bzProcsNo : "",                             // 업무처리번호 — 신규
        haltTpCd : haltTpCd,                        // 정지해제구분
        gubun : "",                                 // 종목코드 구분
        selectGubun : scwin.SELECT_GUBUN_ALL,       // 선택 구분 (원본 select_gubun)
        fstDtectDd : info.fstDtectDd,               // 최초지정일
        designDd : scwin.nextDd,                    // 매매거래정지일 기본값 = 익영업일
        inqDd : inqDd,                              // 조회일
        rsnCd : scwin.HALT_RSN_CD,                  // 사유코드 (원본 arrRsn1)
        rsnNm : scwin.HALT_RSN_NM,                  // 사유명 (원본 arrRsn2)
        rsnDsc : "",                                // 사유설명 (원본 arrRsn3)
        remk : scwin.HALT_REMK[haltTpCd] ?? "",     // 비고 기본 문구
        isuCd : info.isuCd,                         // 종목코드
        isuNm : info.isuNm                          // 종목명
    };
};

