/**
 * @method
 * @name scwin.openHaltPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 정지해제구분에 맞는 매매거래정지 팝업(0 ULDSTF09043 · 1 ULDSTF09044 · 2 ULDSTF09042)을 data 로 열고 닫힐 때까지 기다린다.
 * 닫히면 신규등록구분을 비우고, 저장하고 닫혔거나 창 닫기(X)로 닫혔으면 매매거래정지 탭을 다시 조회하고 연 행을 다시 선택한다.
 * (원본 fn_new_create_frame_trdHalt·fn_update_create_frame_trdHalt — §6.5, 가이드 §6.5)
 * @param {String} haltTpCd 정지해제구분
 * @param {Object} data 팝업 data
 * @param {Object} info 행 정보 (행 복원용)
 * @param {Number} rowIndex 행 인덱스. 신규 버튼은 -1
 * @returns
 * @hidden N
 */
scwin.openHaltPopup = async function (haltTpCd, data, info, rowIndex) {
    const popup = scwin.HALT_POPUPS[haltTpCd];
    if (!popup) {
        // 구분 없는 행으로 신규를 열려는 경우 — 원본은 빈 화면 ID 로 열었다(§8 #6)
        await $c.win.alert($c.data.getMessage("com_req_select", "신규등록구분"));
        sbx_registType.focus();
        return;
    }

    const options = {
        id : popup.popupId,
        popupName : $c.lc.getSecuGrpNm(scwin.SECUGRP_ID) + " " + popup.name,
        width : 850,
        height : popup.height,
        frameModal : "top",
        type : "pageFramePopup"
    };
    const res = await $c.win.openPopup(scwin.POPUP_PATH + popup.popupId + ".xml", options, data);

    sbx_registType.setValue("");    // 원본 sbx_registType.setSelectedIndex(0)
    if (res?.isSaved !== true && res?.isCloseButtonClick !== true) return;
    if (!await scwin.searchList(scwin.TAB_HALT)) return;
    scwin.restoreRow(scwin.TAB_HALT, info.bzProcsNo, info.isuCd, rowIndex);
};

/**
 * @method
 * @name scwin.restoreRow
 * @author Inswave
 * @date 2026. 10. 30
 * @description 다시 조회한 탭 목록에서 팝업을 연 행을 다시 선택한다 — 종목코드·업무처리번호가 같은 행, 없으면 같은 종목의 첫 행
 * (신규 등록 뒤에는 번호가 생겨 달라진다), 그래도 없으면 원래 행 번호. 신규 버튼은 선택하지 않는다. (pf 공통 계약 「행 포커스 복원은 부모가」)
 * @param {Number} index 탭 index (0~5)
 * @param {String} bzProcsNo 업무처리번호
 * @param {String} isuCd 종목코드
 * @param {Number} rowIndex 팝업을 열 때의 행 인덱스 (신규 버튼 -1)
 * @returns
 * @hidden N
 */
scwin.restoreRow = function (index, bzProcsNo, isuCd, rowIndex) {
    if (rowIndex < 0) return;

    const comp = scwin.getTabComp(index);
    const rowCount = comp.dlt.getRowCount();
    if (rowCount === 0) return;

    let focusRow = -1;
    for (let i = 0; i < rowCount; i++) {
        if (String(comp.dlt.getCellData(i, "isuCd") ?? "") !== isuCd) continue;
        if (String(comp.dlt.getCellData(i, "bzProcsNo") ?? "") === bzProcsNo) {
            focusRow = i;
            break;
        }
        if (focusRow < 0) focusRow = i;
    }
    if (focusRow < 0 && rowIndex < rowCount) focusRow = rowIndex;
    if (focusRow >= 0) comp.grd.setFocusedCell(focusRow, 0);
};

/**
 * @method
 * @name scwin.excelDown
 * @author Inswave
 * @date 2026. 10. 30
 * @description 선택된 탭 목록을 엑셀로 내려받는다. 0건이면 안내만 한다. 파일명은 규칙 42(화면ID_이름_시각.xlsx), 시트명은 원본 그대로 탭 이름. (원본 btn_excel_onclick — §6.6)
 * @returns
 * @hidden N
 */
scwin.excelDown = async function () {
    const index = MaxTab_1.getSelectedTabIndex();
    const comp = scwin.getTabComp(index);

    if (comp.dlt.getRowCount() === 0) {
        await $c.win.alert($c.data.getMessage("com_search_0010"));
        return;
    }

    $c.data.downloadGridViewExcel(comp.grd, {
        fileName : $c.win.getProgramId() + "_투자유의_" + $c.date.getServerDateTime("yyyyMMddHHmmss") + ".xlsx",
        sheetName : $c.lc.getSecuGrpNm(scwin.SECUGRP_ID) + "투자유의 " + scwin.TABS[index].name
    });
};
